import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../logic/score_history_service.dart';

/// Shows server-pushed analysis notifications/insights.
/// Each insight is generated by the server based on CAS scores
/// and pushed to the app every 5 minutes with the analysis response.
class NotificationLogScreen extends StatelessWidget {
  const NotificationLogScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final history = context.watch<ScoreHistoryService>();
    final notifications = history.serverNotifications;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Insights'),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Fetch Now',
            onPressed: () {
              history.fetchAndStore();
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text('Fetching fresh analysis...'),
                  duration: Duration(seconds: 1),
                ),
              );
            },
          ),
        ],
      ),
      body: notifications.isEmpty
          ? Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(
                    Icons.notifications_active,
                    size: 64,
                    color: Colors.white24,
                  ),
                  const SizedBox(height: 12),
                  const Text(
                    'No insights yet',
                    style: TextStyle(color: Colors.white54, fontSize: 16),
                  ),
                  const SizedBox(height: 4),
                  const Text(
                    'Server analysis arrives every 5 minutes',
                    style: TextStyle(color: Colors.white24, fontSize: 12),
                  ),
                ],
              ),
            )
          : ListView.builder(
              itemCount: notifications.length,
              padding: const EdgeInsets.all(12),
              itemBuilder: (context, index) {
                final n = notifications[index];
                return _buildInsightCard(context, n);
              },
            ),
    );
  }

  Widget _buildInsightCard(BuildContext context, Map<String, dynamic> n) {
    final type = n['type'] ?? 'info';
    final title = n['title'] ?? '';
    final body = n['body'] ?? '';
    final timeStr = n['time'] ?? '';
    final cas = n['cas'];

    // Parse time
    String displayTime = '';
    try {
      final dt = DateTime.parse(timeStr);
      displayTime =
          '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
    } catch (_) {}

    // Type styling
    Color typeColor;
    IconData typeIcon;
    Color bgColor;
    switch (type) {
      case 'success':
        typeColor = Colors.greenAccent;
        typeIcon = Icons.check_circle;
        bgColor = Colors.greenAccent.withAlpha(15);
        break;
      case 'warning':
        typeColor = Colors.orangeAccent;
        typeIcon = Icons.warning_rounded;
        bgColor = Colors.orangeAccent.withAlpha(15);
        break;
      default:
        typeColor = Colors.lightBlueAccent;
        typeIcon = Icons.info_rounded;
        bgColor = Colors.lightBlueAccent.withAlpha(15);
    }

    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      color: bgColor,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(12),
        side: BorderSide(color: typeColor.withAlpha(40), width: 1),
      ),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            CircleAvatar(
              radius: 18,
              backgroundColor: typeColor.withAlpha(30),
              child: Icon(typeIcon, color: typeColor, size: 20),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      fontSize: 14,
                      color: typeColor,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    body,
                    style: const TextStyle(
                      fontSize: 13,
                      color: Colors.white70,
                      height: 1.3,
                    ),
                  ),
                  const SizedBox(height: 6),
                  Row(
                    children: [
                      if (cas != null) ...[
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 6,
                            vertical: 2,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.white10,
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Text(
                            'CAS: ${(cas as num).toStringAsFixed(0)}',
                            style: const TextStyle(
                              fontSize: 10,
                              color: Colors.white38,
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                      ],
                      const Spacer(),
                      Text(
                        displayTime,
                        style: const TextStyle(
                          fontSize: 11,
                          color: Colors.white30,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
